package com.bplus.share;
import org.json.*;import java.io.*;import java.util.*;
/** Receiver-local receipt ledger. No remote filename or path can select bytes. */
public final class Recall {
 public interface Erase{boolean erase(String uri);}
 static String ledger(String from,String id){return "receipt_"+from+"_"+id;}
 static boolean valid(String s){return s!=null&&s.matches("[a-f0-9]{64}");}
 public static String secret(){return UUID.randomUUID().toString().replace("-","")+UUID.randomUUID().toString().replace("-","");}
 public static void authenticate(JSONObject peer,String ip,String token)throws Exception{if(peer==null||!peer.optString("ip").equals(ip)||token==null||token.isEmpty()||!peer.optString("token").equals(token))throw new IOException("Unverified sender");}
 public static synchronized boolean exists(String from,String id,String key)throws Exception{String raw=Store.get(ledger(from,id),"");if(raw.isEmpty())return false;if(!new JSONObject(raw).optString("key").equals(key))throw new IOException("Receipt collision");return true;}
 public static synchronized void received(String from,String id,String key,String kind,String uri)throws Exception{if(!valid(id)||!valid(key))throw new IOException("Invalid receipt");String slot=ledger(from,id);String old=Store.get(slot,"");if(!old.isEmpty()){JSONObject previous=new JSONObject(old);if(!previous.optString("key").equals(key))throw new IOException("Receipt collision");throw new IOException("Duplicate receipt");}JSONObject r=new JSONObject().put("key",key).put("kind",kind).put("uri",uri).put("status","received");Store.set(slot,r.toString());}
 public static synchronized JSONObject handle(JSONObject b,String ip,Erase erase)throws Exception{String from=b.optString("from"),id=b.optString("id"),key=b.optString("key");authenticate(Store.peerById(from),ip,b.optString("token"));if(!valid(id)||!valid(key))throw new IOException("Invalid receipt");String slot=ledger(from,id),raw=Store.get(slot,"");if(raw.isEmpty())return new JSONObject().put("status","unknown");JSONObject r=new JSONObject(raw);if(!key.equals(r.optString("key")))throw new IOException("Wrong receipt key");if(r.optString("status").equals("deleted"))return new JSONObject().put("status","deleted");if(r.optString("kind").equals("file")&&!erase.erase(r.optString("uri")))return new JSONObject().put("status","file_refused");JSONArray t=Store.thread(from),keep=new JSONArray();for(int i=0;i<t.length();i++){JSONObject m=t.optJSONObject(i);if(m!=null&&!(id.equals(m.optString("wireId"))&&!m.optBoolean("me")))keep.put(m);}Store.saveThread(from,keep);r.put("status","deleted");r.remove("uri");Store.set(slot,r.toString());return new JSONObject().put("status","deleted");}
 public static synchronized void retireUri(String uri){try{JSONArray a=new JSONArray(Store.get("library","[]")),keep=new JSONArray();for(int i=0;i<a.length();i++){JSONObject m=a.optJSONObject(i);if(m!=null&&!uri.equals(m.optString("uri")))keep.put(m);}Store.set("library",keep.toString());}catch(Exception ignored){}}
}
